node -e "
const sqlite3 = require('better-sqlite3');
const db = new sqlite3('/workspace/world.db');

const orderId = '#W4705780';
const oldItemId = '9716794911';
const newItemId = '2364909101';
const paymentMethodId = 'paypal_5098475';

// Get new variant details
const newVariant = db.prepare(\"SELECT * FROM rt_variants WHERE item_id = ?\").get(newItemId);
const newOptions = newVariant.options;
const newPrice = newVariant.price;
const oldPrice = 54.99;
const diffPrice = Math.round((newPrice - oldPrice) * 100) / 100;

console.log('Price difference:', diffPrice);

// Update order status
db.prepare(\"UPDATE orders SET status = 'pending (item modified)' WHERE order_id = ?\").run(orderId);

// Update the order item
db.prepare(\"UPDATE order_items SET item_id = ?, unit_price = ?, options = ? WHERE order_id = ? AND item_id = ?\").run(newItemId, newPrice, newOptions, orderId, oldItemId);

// Add refund payment record (diff is negative, so it's a refund)
const txnType = diffPrice > 0 ? 'payment' : 'refund';
const amount = Math.abs(diffPrice);
db.prepare(\"INSERT INTO order_payments (order_id, transaction_type, amount, payment_method_id) VALUES (?, ?, ?, ?)\").run(orderId, txnType, amount, paymentMethodId);

// Verify the changes
const order = db.prepare('SELECT * FROM orders WHERE order_id = ?').get(orderId);
console.log('Updated Order Status:', order.status);

const items = db.prepare('SELECT * FROM order_items WHERE order_id = ?').all(orderId);
for (const item of items) {
  console.log('  Item:', item.name, '| Item ID:', item.item_id, '| Options:', item.options, '| Price:', item.unit_price);
}

const payments = db.prepare('SELECT * FROM order_payments WHERE order_id = ?').all(orderId);
for (const p of payments) {
  console.log('  Payment:', p.transaction_type, '| Amount:', p.amount, '| Method:', p.payment_method_id);
}

db.close();
console.log('\\nOrder updated successfully!');
"
